// webpack.min.js —— 用 MinChunkSizePlugin 合并掉过小的 chunk
// 当某个 chunk 体积小于 minChunkSize 字节时，会被合并到其他 chunk
const path = require("path");
const webpack = require("webpack");

module.exports = {
  mode: "production",
  entry: "./src/index.js",
  output: {
    path: path.resolve(__dirname, "dist/min"),
    filename: "[name].js",
    chunkFilename: "[name].chunk.js",
    clean: true,
  },
  plugins: [
    new webpack.optimize.MinChunkSizePlugin({
      minChunkSize: 10 * 1024, // 小于 10KB 的 chunk 会被合并
    }),
  ],
};
